def text_scope_flags(advisory: PublicAdvisory, raw: dict[str, Any]) -> list[str]:
    """Conservative exclusions, not a claim that every cue is an actual prerequisite."""
    descriptions = [advisory.description] + [
        d["value"]
        for d in raw["containers"]["cna"].get("descriptions", [])
        if d.get("lang") == "en" and isinstance(d.get("value"), str)
    ]
    return sorted(
        {
            match.group().casefold()
            for text in descriptions
            for match in TEXT_SCOPE_CUES.finditer(text)
        }
    )


def identity(product: dict[str, Any], advisory: PublicAdvisory) -> set[tuple[str, str]]:
    cpes = product.get("cpes") or []
    if cpes:
        pairs = set()
        for cpe in cpes:
            part, vendor, name, cpe_version, *extra = split_cpe(cpe)
            if (
                part != "a"
                or cpe_version != "*"
                or any(x != "*" for x in extra)
                or any(c in vendor + name for c in "*?")
            ):
                raise Unsupported("cna_cpe_constraints")
            pairs.add((vendor.casefold(), name.casefold()))
        if not pairs <= advisory.products:
            raise Unsupported("cna_cpe_product_mismatch")
        return pairs
    raw_vendor, raw_name = product.get("vendor"), product.get("product")
    if not isinstance(raw_vendor, str) or not isinstance(raw_name, str):
        raise Unsupported("cna_missing_product_identity")
    vendor_key = VENDOR_ALIASES.get(folded(raw_vendor), folded(raw_vendor))
    name_key = PRODUCT_ALIASES.get((vendor_key, folded(raw_name)), folded(raw_name))
    matches = {
        (v, p) for v, p in advisory.products if folded(v) == vendor_key and folded(p) == name_key
    }
    if len(matches) != 1:
        raise Unsupported("cna_product_identity_not_confirmed")
    return matches


def entry_matches(entry: dict[str, Any], version: str) -> bool:
    start = entry["version"]
    if "lessThan" not in entry and "lessThanOrEqual" not in entry:
        return compare(version, start) == 0
    upper = str(entry.get("lessThan", entry.get("lessThanOrEqual")))
    return compare(version, start) >= 0 and (
        upper == "*"
        or compare(version, upper) < 0
        or ("lessThanOrEqual" in entry and compare(version, upper) == 0)
    )


def status_for(product: dict[str, Any], version: str) -> str:
    """CNA raw-status evaluation, separate from the NVD Criterion implementation."""
    matching = [e for e in product["versions"] if entry_matches(e, version)]
    if len(matching) > 1:
        raise Unsupported("cna_overlapping_version_entries")
    return str(matching[0]["status"]) if matching else str(product.get("defaultStatus", "unknown"))


def probes(bounds: set[tuple[int, ...]]) -> list[str]:
    """One point in every constant-truth cell, including exact boundaries and unbounded tail."""
    ordered = sorted(bounds | {(0,)})
    points = set(ordered)
    for lower, upper in zip(ordered, ordered[1:], strict=False):
        between = lower + (0,) * max(0, len(upper) - len(lower)) + (1,)
        if not lower < between < upper:
            raise ValueError("failed to construct an interior numeric interval witness")
        points.add(between)
    points.add(ordered[-1] + (1,))
    return [".".join(map(str, point)) for point in sorted(points)]


def corroborate(advisory: PublicAdvisory, raw: dict[str, Any]) -> dict[str, Any]:
    if (
        raw.get("dataType") != "CVE_RECORD"
        or raw.get("cveMetadata", {}).get("cveId") != advisory.id
        or raw.get("cveMetadata", {}).get("state") != "PUBLISHED"
    ):
        raise Unsupported("cna_identity_or_publication_state")
    cna = raw["containers"]["cna"]
    affected = cna.get("affected")
    if not isinstance(affected, list) or not affected:
        raise Unsupported("cna_missing_affected")
    mapped: dict[tuple[str, str], dict[str, Any]] = {}
    for product in affected:
        # The initial audit demonstrated that omitted/unknown defaults cannot support
        # arbitrary version negatives. No source status is silently imputed here.
        if product.get("defaultStatus", "unknown") != "unaffected":
            raise Unsupported("cna_unknown_or_nonnegative_default")
        if any(product.get(k) for k in ("platforms", "modules", "programFiles", "programRoutines")):
            raise Unsupported("cna_additional_platform_or_component_constraints")
        entries = product.get("versions")
        if not isinstance(entries, list) or not entries or len(entries) > 32:
            raise Unsupported("cna_missing_or_excessive_versions")
        for entry in entries:
            if entry.get("status") != "affected" or entry.get("changes"):
                raise Unsupported("cna_explicit_status_override_or_unknown")
            numeric(entry["version"])
            if "lessThan" in entry and "lessThanOrEqual" in entry:
                raise Unsupported("cna_conflicting_upper_bounds")
            if "lessThan" in entry or "lessThanOrEqual" in entry:
                if entry.get("versionType") not in ("semver", "custom"):
                    raise Unsupported("cna_unsupported_version_type")
                upper = entry.get("lessThan", entry.get("lessThanOrEqual"))
                if upper != "*":
                    numeric(upper)
                    comparison = compare(entry["version"], upper)
                    if comparison > 0 or (comparison == 0 and "lessThan" in entry):
                        raise Unsupported("cna_empty_or_inverted_range")
        for pair in identity(product, advisory):
            if pair in mapped:
                raise Unsupported("cna_duplicate_product_scopes")
            mapped[pair] = product
    if set(mapped) != advisory.products:
        raise Unsupported("cna_incomplete_product_coverage")
    checked = []
    for (vendor, name), product in sorted(mapped.items()):
        bounds = {
            numeric(value)
            for term in advisory.terms
            if term.product_key == (vendor, name)
            for value in (term.exact, term.lower, term.upper)
            if value is not None
        }
        bounds.update(
            numeric(value)
            for entry in product["versions"]
            for value in (entry["version"], entry.get("lessThan"), entry.get("lessThanOrEqual"))
            if value not in (None, "*")
        )
        for version in probes(bounds):
            status = status_for(product, version)
            applicable = advisory.applies((Installed(vendor, name, version),))
            if status not in ("affected", "unaffected") or applicable != (status == "affected"):
                raise Unsupported("nvd_cna_numeric_predicate_disagreement")
            checked.append(
                {"vendor": vendor, "product": name, "version": version, "status": status}
            )
    return {
        "cve_id": advisory.id,
        "contract": CONTRACT,
        "status": "corroborated",
        "products": [list(p) for p in sorted(mapped)],
        "boundary_and_cell_checks": checked,
        "cna_provider": cna.get("providerMetadata"),
        "scope": "Agreement of complete explicit affected/unaffected numeric predicates; no unknown defaults, platform/module requirements or full ecosystem-version conformance.",
    }

payload.benchmark/model.py:
"""Research profile records with local labels and a separate provider-visible view."""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
from typing import Any

from ..domain import render_executor_input
from .oracle import Criterion, Installed, PublicAdvisory


@dataclass(frozen=True)
class BenchmarkProfile:
    id: str
    partition: str
    text: str
    components: tuple[Installed, ...]
    advisories: tuple[PublicAdvisory, ...]
    expected: tuple[str, ...]
    stratum: str
    anchor_cve: str
    presentation: dict[str, Any] = field(default_factory=dict)

    def executor_input(self, *, structured_inventory: bool = False) -> dict[str, Any]:
        prose = self.presentation.get("prose_advisories", {})
        advisories = [
            {**a.executor_input(), **({"affected": prose[a.id]["text"]} if a.id in prose else {})}
            for a in self.advisories
        ]
        return render_executor_input(
            self.text,
            [asdict(c) for c in self.components],
            advisories,
            structured_inventory=structured_inventory,
        )

    def record(self) -> dict[str, Any]:
        return {**asdict(self), "advisories": [a.id for a in self.advisories]}


def restore_advisory(row: dict[str, Any]) -> PublicAdvisory:
    return PublicAdvisory(**{**row, "terms": tuple(Criterion(**t) for t in row["terms"])})


def restore_profile(row: dict[str, Any], advisories: dict[str, PublicAdvisory]) -> BenchmarkProfile:
    return BenchmarkProfile(
        **{
            **row,
            "components": tuple(Installed(**c) for c in row["components"]),
            "advisories": tuple(advisories[a] for a in row["advisories"]),
            "expected": tuple(row["expected"]),
        }
    )


def score(profile: BenchmarkProfile, prediction: list[str] | None, status: str) -> dict[str, Any]:
    truth = set(profile.expected)
    allowed = {a.id for a in profile.advisories}
    categories = []
    if prediction is None:
        tp, fp, fn = 0, len(allowed - truth), len(truth)
        categories = [
            "transport_failure"
            if status in ("transport_failure", "request_rejected")
            else "invalid_output"
        ]
    else:
        predicted = set(prediction)
        tp, fp, fn = len(predicted & truth), len(predicted - truth), len(truth - predicted)
        for advisory in profile.advisories:
            if advisory.id in predicted - truth:
                categories.append(
                    "version_excluded"
                    if any(advisory.matches_product(c) for c in profile.components)
                    else "unrelated_product"
                )
            elif advisory.id in truth - predicted:
                categories.append("missed_applicable")
    return {
        "profile_id": profile.id,
        "partition": profile.partition,
        "stratum": profile.stratum,
        "status": status,
        "prediction": prediction,
        "expected": sorted(truth),
        "tp": tp,
        "fp": fp,
        "fn": fn,
        "valid": prediction is not None,
        "categories": categories,
    }

payload.benchmark/oracle.py:
"""Conservative NVD OR/application projection; not universal CPE/version conformance."""

from __future__ import annotations

import re
from dataclasses import asdict, dataclass
from typing import Any

from ..storage import digest

SEMANTICS = "nvd-or-application-numeric-v1"


class Unsupported(ValueError):
    """A source condition has no label under this contract."""


def numeric(value: str) -> tuple[int, ...]:
    if (
        not isinstance(value, str)
        or len(value) > 100
        or not re.fullmatch(r"(?:0|[1-9][0-9]*)(?:\.(?:0|[1-9][0-9]*))*", value)
    ):
        raise Unsupported("unsupported_numeric_version")
    parts = tuple(int(item) for item in value.split("."))
    while len(parts) > 1 and parts[-1] == 0:
        parts = parts[:-1]
    return parts


def split_cpe(criteria: str) -> tuple[str, ...]:
    if not isinstance(criteria, str) or len(criteria) > 2048:
        raise Unsupported("invalid_cpe")
    fields, buffer, escaped = [], [], False
    for char in criteria:
        if escaped:
            if not char.isascii() or char.isalnum() or char.isspace() or char in "*?":
                raise Unsupported("unsupported_cpe_escape")
            buffer.append(char)
            escaped = False
        elif char == "\\":
            escaped = True
        elif char == ":":
            fields.append("".join(buffer))
            buffer = []
        elif char.isascii() and (char.isalnum() or char in "_.-*?"):
            buffer.append(char)
        else:
            raise Unsupported("invalid_cpe_character")
    fields.append("".join(buffer))
    if escaped or len(fields) != 13 or fields[:2] != ["cpe", "2.3"]:
        raise Unsupported("invalid_cpe")
    return tuple(fields[2:])


@dataclass(frozen=True)
class Installed:
    vendor: str
    product: str
    version: str
    part: str = "a"


@dataclass(frozen=True)
class Criterion:
    vendor: str
    product: str
    exact: str | None
    lower: str | None
    upper: str | None
    lower_inclusive: bool
    upper_inclusive: bool
    criteria: str
    match_criteria_id: str | None

    @property
    def product_key(self) -> tuple[str, str]:
        return self.vendor, self.product

    def matches_product(self, component: Installed) -> bool:
        return component.part == "a" and self.product_key == (
            component.vendor.casefold(),
            component.product.casefold(),
        )

    def applies(self, component: Installed) -> bool:
        if not self.matches_product(component):
            return False
        value = numeric(component.version)
        if self.exact is not None:
            return value == numeric(self.exact)
        if self.lower is not None:
            lower = numeric(self.lower)
            if value < lower or (value == lower and not self.lower_inclusive):
                return False
        if self.upper is not None:
            upper = numeric(self.upper)
            if value > upper or (value == upper and not self.upper_inclusive):
                return False
        return True

    def render(self) -> str:
        if self.exact is not None:
            bounds = "version = " + self.exact
        else:
            pieces = []
            if self.lower is not None:
                pieces.append((">= " if self.lower_inclusive else "> ") + self.lower)
            if self.upper is not None:
                pieces.append(("<= " if self.upper_inclusive else "< ") + self.upper)
            bounds = "version " + " and ".join(pieces) if pieces else "all numeric versions"
        return f"{self.vendor}/{self.product}: {bounds}"


def parse_criterion(match: dict[str, Any]) -> Criterion:
    if match.get("vulnerable") is not True:
        raise Unsupported("nonvulnerable_or_prerequisite")
    criteria = match.get("criteria")
    if not isinstance(criteria, str):
        raise Unsupported("invalid_cpe")
    fields = split_cpe(criteria)
    part, vendor, product, exact, *extra = fields
    if part != "a":
        raise Unsupported("nonapplication_cpe")
    if any(not item or item == "-" or "*" in item or "?" in item for item in (vendor, product)):
        raise Unsupported("nonliteral_product")
    if extra != ["*"] * 7:
        raise Unsupported("additional_cpe_constraints")
    lower_values = [
        match[k] for k in ("versionStartIncluding", "versionStartExcluding") if k in match
    ]
    upper_values = [match[k] for k in ("versionEndIncluding", "versionEndExcluding") if k in match]
    if len(lower_values) > 1 or len(upper_values) > 1:
        raise Unsupported("conflicting_range_endpoints")
    for bound in lower_values + upper_values:
        numeric(bound)
    lower, upper = next(iter(lower_values), None), next(iter(upper_values), None)
    if exact != "*" and (lower is not None or upper is not None):
        raise Unsupported("exact_plus_range")
    for value in (None if exact == "*" else exact, lower, upper):
        if value is not None:
            numeric(value)
    lower_inclusive = "versionStartIncluding" in match
    upper_inclusive = "versionEndIncluding" in match
    if lower is not None and upper is not None:
        if numeric(lower) > numeric(upper) or (
            numeric(lower) == numeric(upper) and not (lower_inclusive and upper_inclusive)
        ):
            raise Unsupported("empty_or_inverted_range")
    return Criterion(
        vendor.casefold(),
        product.casefold(),
        None if exact == "*" else exact,
        lower,
        upper,
        lower_inclusive,
        upper_inclusive,
        match["criteria"],
        match.get("matchCriteriaId"),
    )


@dataclass(frozen=True)
class PublicAdvisory:
    id: str
    description: str
    published: str
    last_modified: str
    terms: tuple[Criterion, ...]
    source_sha256: str

    @property
    def products(self) -> set[tuple[str, str]]:
        return {term.product_key for term in self.terms}

    def applies(self, components: tuple[Installed, ...]) -> bool:
        return any(term.applies(component) for term in self.terms for component in components)

    def matches_product(self, component: Installed) -> bool:
        return any(term.matches_product(component) for term in self.terms)

    def executor_input(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "description": self.description,
            "affected": " OR ".join(term.render() for term in self.terms),
        }

    def record(self) -> dict[str, Any]:
        return asdict(self)


def parse_advisory(raw: dict[str, Any]) -> PublicAdvisory:
    if not isinstance(raw.get("id"), str) or not re.fullmatch(r"CVE-[0-9]{4}-[0-9]{4,}", raw["id"]):
        raise Unsupported("invalid_cve_id")
    if raw.get("vulnStatus") in {"Rejected", "Deferred"}:
        raise Unsupported("rejected_or_deferred")
    description = next(
        (d["value"] for d in raw.get("descriptions", []) if d.get("lang") == "en"), ""
    )
    if not isinstance(description, str) or not description.strip():
        raise Unsupported("missing_english_description")
    if len(description) > 4000:
        raise Unsupported("description_over_4000_characters")
    configurations = raw.get("configurations")
    if not isinstance(configurations, list) or not configurations:
        raise Unsupported("missing_configurations")
    terms: list[Criterion] = []
    for config in configurations:
        if "children" in config or "cpeMatch" in config:
            raise Unsupported("unsupported_configuration_layout")
        nodes = config.get("nodes")
        if not isinstance(nodes, list) or not nodes:
            raise Unsupported("missing_nodes")
        if config.get("negate", False) is not False or config.get("operator", "OR") != "OR":
            raise Unsupported("non_or_or_negated_configuration")
        if "operator" not in config and len(nodes) != 1:
            raise Unsupported("implicit_operator_multiple_nodes")
        for node in nodes:
            if node.get("operator") != "OR" or node.get("negate", False) is not False:
                raise Unsupported("non_or_or_negated_node")
            if "children" in node or "nodes" in node:
                raise Unsupported("nested_nodes")
            matches = node.get("cpeMatch")
            if not isinstance(matches, list) or not matches:
                raise Unsupported("missing_cpe_matches")
            terms.extend(parse_criterion(match) for match in matches)
    if len(terms) > 16:
        raise Unsupported("more_than_16_or_terms")
    if not raw.get("published") or not raw.get("lastModified"):
        raise Unsupported("missing_source_dates")
    return PublicAdvisory(
        raw["id"], description, raw["published"], raw["lastModified"], tuple(terms), digest(raw)
    )

payload.benchmark/reference.py:
"""Separate raw-CPE label checker; intentionally imports no production oracle helpers.

Agreement checks implementation consistency, not the correctness of NVD annotations.
"""

from __future__ import annotations

import itertools
import re
from typing import Any


def compare(left: str, right: str) -> int:
    values = []
    for value in (left, right):
        if not isinstance(value, str) or len(value) > 100:
            raise ValueError("unsupported reference version")
        pieces = value.split(".")
        if any(
            not p.isascii() or not p.isdecimal() or (len(p) > 1 and p[0] == "0") for p in pieces
        ):
            raise ValueError("unsupported reference version")
        values.append([int(p) for p in pieces])
    for a, b in itertools.zip_longest(*values, fillvalue=0):
        if a != b:
            return 1 if a > b else -1
    return 0


def names(criteria: str) -> list[str]:
    token = r"(?:\\.|[^:\\])+"
    if re.fullmatch((token + ":") * 12 + token, criteria) is None:
        raise ValueError("invalid reference CPE")
    fields = [re.sub(r"\\(.)", r"\1", item) for item in re.findall(token, criteria)]
    if fields[:3] != ["cpe", "2.3", "a"] or fields[6:] != ["*"] * 7:
        raise ValueError("unsupported reference CPE")
    if re.search(r"\\[?*]", criteria) or any(
        not item or item == "-" or "*" in item or "?" in item for item in fields[3:5]
    ):
        raise ValueError("unsupported reference product")
    return fields


def check(raw: dict[str, Any], components: list[dict[str, str]]) -> bool:
    decisions = []
    configurations = raw.get("configurations")
    if not configurations:
        raise ValueError("missing reference configurations")
    for config in configurations:
        if config.get("operator", "OR") != "OR" or config.get("negate", False) is not False:
            raise ValueError("unsupported reference configuration")
        nodes = config["nodes"]
        if not nodes or ("operator" not in config and len(nodes) != 1):
            raise ValueError("ambiguous reference nodes")
        for node in nodes:
            if node.get("operator") != "OR" or node.get("negate", False) is not False:
                raise ValueError("unsupported reference node")
            if "children" in node or "nodes" in node or not node.get("cpeMatch"):
                raise ValueError("unsupported reference nesting")
            for match in node["cpeMatch"]:
                if match.get("vulnerable") is not True:
                    raise ValueError("unsupported reference prerequisite")
                fields = names(match["criteria"])
                exact = fields[5]
                bounds = {
                    k: match[k]
                    for k in (
                        "versionStartIncluding",
                        "versionStartExcluding",
                        "versionEndIncluding",
                        "versionEndExcluding",
                    )
                    if k in match
                }
                if exact != "*" and bounds:
                    raise ValueError("reference exact/range conflict")
                for component in components:
                    product_match = component.get("part", "a") == "a" and (
                        component["vendor"].casefold(),
                        component["product"].casefold(),
                    ) == (fields[3].casefold(), fields[4].casefold())
                    version = component["version"]
                    predicates = []
                    if exact != "*":
                        predicates.append(compare(version, exact) == 0)
                    for name, bound in bounds.items():
                        comparison = compare(version, bound)
                        predicates.append(
                            {
                                "versionStartIncluding": comparison >= 0,
                                "versionStartExcluding": comparison > 0,
                                "versionEndIncluding": comparison <= 0,
                                "versionEndExcluding": comparison < 0,
                            }[name]
                        )
                    decisions.append(product_match and all(predicates))
    return any(decisions)

payload.domain.py:
"""Strict fixture semantics, response contracts, metrics, and tier feedback."""

from __future__ import annotations

import json
import re
from dataclasses import asdict, dataclass
from typing import Any

SEMANTICS = "synthetic-numeric-or-v1"
PARSER = "strict-json-v1"
BASELINE = "Return applicable_cves as JSON. Consider the candidate advisories."
TASK = (
    "Improve a prompt for applicability matching. Return exactly one JSON object with a "
    "nonempty prompt string. Executor output must be an object containing applicable_cves, "
    "an array of unique supplied advisory identifiers. Numeric fixture versions compare "
    "as integers per component, with trailing zeros equivalent. Match vendor and product."
)
ABSTRACTIONS = {
    "unrelated_product": "A predicted advisory does not match an installed vendor/product.",
    "version_excluded": "An installed product matches but its version is outside the affected range.",
    "missed_applicable": "An applicable advisory was omitted.",
    "invalid_output": "The response violates the required output contract.",
    "transport_failure": "An evaluation has no usable provider response.",
}


class ContractError(ValueError):
    """Input is outside the explicit benchmark or response contract."""


def strict_json(text: str) -> Any:
    def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in items:
            if key in result:
                raise ContractError(f"duplicate JSON key: {key}")
            result[key] = value
        return result

    def constant(value: str) -> Any:
        raise ContractError(f"non-finite JSON constant: {value}")

    try:
        return json.loads(text, object_pairs_hook=pairs, parse_constant=constant)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ContractError("response is not strict JSON") from exc


def version(value: str) -> tuple[int, ...]:
    """Only synthetic dotted nonnegative integers; not a universal CPE comparator."""
    if not isinstance(value, str) or not re.fullmatch(r"\d+(?:\.\d+)*", value, flags=re.ASCII):
        raise ContractError(f"unsupported synthetic version: {value!r}")
    parts = [int(item) for item in value.split(".")]
    while len(parts) > 1 and parts[-1] == 0:
        parts.pop()
    return tuple(parts)


@dataclass(frozen=True)
class Component:
    vendor: str
    product: str
    version: str


@dataclass(frozen=True)
class Advisory:
    id: str
    description: str
    vendor: str
    product: str
    exact: str | None = None
    start: str | None = None
    end: str | None = None
    start_inclusive: bool = True
    end_inclusive: bool = False

    def matches_product(self, component: Component) -> bool:
        return (self.vendor, self.product) == (component.vendor, component.product)

    def applies(self, component: Component) -> bool:
        if not self.matches_product(component):
            return False
        installed = version(component.version)
        if self.exact is not None:
            return installed == version(self.exact)
        if self.start is not None:
            lower = version(self.start)
            if installed < lower or (installed == lower and not self.start_inclusive):
                return False
        if self.end is not None:
            upper = version(self.end)
            if installed > upper or (installed == upper and not self.end_inclusive):
                return False
        return True


@dataclass(frozen=True)
class Profile:
    id: str
    partition: str
    text: str
    components: tuple[Component, ...]
    advisories: tuple[Advisory, ...]
    expected: tuple[str, ...]

    def executor_input(self, *, structured_inventory: bool = False) -> dict[str, Any]:
        # Labels and partition metadata deliberately never enter the provider request.
        return render_executor_input(
            self.text,
            [asdict(c) for c in self.components],
            [asdict(a) for a in self.advisories],
            structured_inventory=structured_inventory,
        )


def render_executor_input(
    text: str,
    components: list[dict[str, Any]],
    advisories: list[dict[str, Any]],
    *,
    structured_inventory: bool = False,
) -> dict[str, Any]:
    result: dict[str, Any] = {"system_profile": text, "advisories": advisories}
    if structured_inventory:
        result["components"] = components
    return result


def load_profiles(data: dict[str, Any]) -> list[Profile]:
    if data.get("semantics") != SEMANTICS:
        raise ContractError("fixture semantics version mismatch")
    profiles: list[Profile] = []
    identifiers: set[str] = set()
    cve_partitions: dict[str, str] = {}
    for row in data["profiles"]:
        try:
            profile = Profile(
                id=row["id"],
                partition=row["partition"],
                text=row["text"],
                components=tuple(Component(**item) for item in row["components"]),
                advisories=tuple(Advisory(**item) for item in row["advisories"]),
                expected=tuple(row["expected"]),
            )
        except (KeyError, TypeError) as exc:
            raise ContractError("invalid profile fixture shape") from exc
        if not re.fullmatch(r"[a-z0-9_-]+", profile.id) or profile.id in identifiers:
            raise ContractError("invalid or duplicate profile ID")
        identifiers.add(profile.id)
        if profile.partition not in {"optimization", "validation", "test"}:
            raise ContractError("unknown partition")
        if not profile.components or not profile.advisories:
            raise ContractError("empty profile inputs")
        for component in profile.components:
            version(component.version)
        cves = [a.id for a in profile.advisories]
        if len(cves) != len(set(cves)):
            raise ContractError("duplicate candidate advisory")
        for advisory in profile.advisories:
            if not re.fullmatch(r"CVE-\d{4}-\d{4,}", advisory.id):
                raise ContractError("invalid advisory ID")
            previous = cve_partitions.setdefault(advisory.id, profile.partition)
            if previous != profile.partition:
                raise ContractError("advisory overlaps partitions")
            if advisory.exact is not None and (
                advisory.start is not None or advisory.end is not None
            ):
                raise ContractError("exact and ranged versions cannot be combined")
            for bound in (advisory.exact, advisory.start, advisory.end):
                if bound is not None:
                    version(bound)
            if not isinstance(advisory.start_inclusive, bool) or not isinstance(
                advisory.end_inclusive, bool
            ):
                raise ContractError("range inclusivity must be boolean")
            if advisory.start is not None and advisory.end is not None:
                if version(advisory.start) > version(advisory.end):
                    raise ContractError("inverted range")
        if len(profile.expected) != len(set(profile.expected)):
            raise ContractError("duplicate expected label")
        computed = {
            a.id for a in profile.advisories if any(a.applies(c) for c in profile.components)
        }
        if computed != set(profile.expected):
            raise ContractError(f"independent fixture labels disagree: {profile.id}")
        profiles.append(profile)
    if {p.partition for p in profiles} != {"optimization", "validation", "test"}:
        raise ContractError("all three partitions are required")
    return profiles


def parse_answer(text: str, allowed: set[str], finish_reason: str = "stop") -> list[str]:
    if finish_reason != "stop":
        raise ContractError(f"incomplete or refused response: {finish_reason}")
    data = strict_json(text)
    if not isinstance(data, dict) or set(data) != {"applicable_cves"}:
        raise ContractError("expected only applicable_cves")
    values = data["applicable_cves"]
    if not isinstance(values, list) or any(not isinstance(v, str) for v in values):
        raise ContractError("applicable_cves must be an array of strings")
    if len(values) != len(set(values)):
        raise ContractError("duplicate prediction")
    if not set(values) <= allowed:
        raise ContractError("prediction includes unknown advisory")
    return sorted(values)


def parse_prompt(text: str, finish_reason: str = "stop") -> str:
    if finish_reason != "stop":
        raise ContractError("optimizer response incomplete")
    data = strict_json(text)
    if not isinstance(data, dict) or set(data) != {"prompt"}:
        raise ContractError("expected exactly one prompt field")
    prompt = data["prompt"]
    if not isinstance(prompt, str) or not prompt.strip() or len(prompt) > 8000:
        raise ContractError("prompt must contain 1–8000 characters")
    return prompt


def score(profile: Profile, prediction: list[str] | None, status: str) -> dict[str, Any]:
    truth = set(profile.expected)
    allowed = {a.id for a in profile.advisories}
    if prediction is None:
        # Conservative all-scheduled bound: each unresolved decision is wrong.
        return {
            "profile_id": profile.id,
            "partition": profile.partition,
            "status": status,
            "prediction": None,
            "expected": sorted(truth),
            "tp": 0,
            "fp": len(allowed - truth),
            "fn": len(truth),
            "valid": False,
            "categories": [
                "transport_failure" if status == "transport_failure" else "invalid_output"
            ],
        }
    predicted = set(prediction)
    categories = []
    for advisory in profile.advisories:
        if advisory.id in predicted - truth:
            categories.append(
                "version_excluded"
                if any(advisory.matches_product(c) for c in profile.components)
                else "unrelated_product"
            )
        elif advisory.id in truth - predicted:
            categories.append("missed_applicable")
    return {
        "profile_id": profile.id,
        "partition": profile.partition,
        "status": status,
        "prediction": prediction,
        "expected": sorted(truth),
        "tp": len(predicted & truth),
        "fp": len(predicted - truth),
        "fn": len(truth - predicted),
        "valid": True,
        "categories": categories,
    }


def metrics(rows: list[dict[str, Any]]) -> dict[str, Any]:
    def pooled(items: list[dict[str, Any]]) -> dict[str, Any]:
        tp, fp, fn = (sum(row[key] for row in items) for key in ("tp", "fp", "fn"))
        return {
            "tp": tp,
            "fp": fp,
            "fn": fn,
            "micro_f1": 2 * tp / (2 * tp + fp + fn) if 2 * tp + fp + fn else 0.0,
            "precision": tp / (tp + fp) if tp + fp else 0.0,
            "recall": tp / (tp + fn) if tp + fn else 0.0,
        }

    valid = [r for r in rows if r["valid"]]
    return {
        "scheduled": len(rows),
        "valid": len(valid),
        "coverage": len(valid) / len(rows) if rows else 0.0,
        "valid_answers": pooled(valid),
        "failure_aware_lower_bound": pooled(rows),
    }


def feedback(
    rows: list[dict[str, Any]],
    profiles: list[Profile],
    tier: int,
) -> dict[str, Any]:
    if tier not in (1, 2, 3):
        raise ContractError("unknown disclosure tier")
    counts = {key: 0 for key in ABSTRACTIONS}
    for row in rows:
        for category in row["categories"]:
            counts[category] += 1
    output: dict[str, Any] = {"metrics": metrics(rows), "error_counts": counts}
    if tier >= 2:
        output["abstractions"] = [
            {"text": ABSTRACTIONS[key], "count": count} for key, count in counts.items() if count
        ]
    if tier == 3:
        by_id = {p.id: p for p in profiles}
        output["examples"] = [
            {
                "input": by_id[row["profile_id"]].executor_input(),
                "prediction": row["prediction"],
                "expected": row["expected"],
            }
            for row in rows
            if row["categories"]
        ][:4]
    return output

payload.live/adapters.py:
"""Explicit request contracts and measured provider-usage normalization."""

from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any

from ..domain import Profile
from ..storage import canonical
from .transport import response_json

PROMPT_SCHEMA = {
    "type": "object",
    "properties": {"prompt": {"type": "string"}},
    "required": ["prompt"],
    "additionalProperties": False,
}


def dollars(value: Any) -> Decimal:
    if isinstance(value, bool) or value is None:
        raise ValueError("USD amount is unavailable or invalid")
    try:
        amount = Decimal(str(value))
    except InvalidOperation as exc:
        raise ValueError("USD amount is not numeric") from exc
    if not amount.is_finite() or amount < 0:
        raise ValueError("USD amount must be finite and nonnegative")
    return amount


def executor_body(
    model: str, prompt: str, profile: Profile, *, think: bool | None = None
) -> dict[str, Any]:
    body: dict[str, Any] = {
        "model": model,
        "stream": False,
        "keep_alive": "5m",
        "truncate": False,
        "shift": False,
        "messages": [
            {"role": "system", "content": prompt},
            {"role": "user", "content": canonical(profile.executor_input())},
        ],
        "format": {
            "type": "object",
            "properties": {
                "applicable_cves": {
                    "type": "array",
                    "items": {"type": "string", "enum": [a.id for a in profile.advisories]},
                }
            },
            "required": ["applicable_cves"],
            "additionalProperties": False,
        },
        "options": {"temperature": 0, "seed": 11, "num_ctx": 8192, "num_predict": 512},
    }
    if think is not None:
        body["think"] = think
    return body


def optimizer_body(
    model: str, endpoint_tag: str, permitted_request: dict[str, Any]
) -> dict[str, Any]:
    return {
        "model": model,
        "stream": False,
        "max_tokens": 8192,
        "temperature": 0,
        "reasoning": {"effort": "low"},
        "provider": {
            "only": [endpoint_tag],
            "order": [endpoint_tag],
            "allow_fallbacks": False,
            "require_parameters": True,
            "quantizations": ["fp8"],
            "max_price": {"prompt": 0.8, "completion": 1.6, "request": 0},
        },
        "response_format": {
            "type": "json_schema",
            "json_schema": {"name": "candidate_prompt", "strict": True, "schema": PROMPT_SCHEMA},
        },
        "messages": [{"role": "user", "content": canonical(permitted_request)}],
    }


def reservation(body: dict[str, Any], endpoint: dict[str, Any]) -> Decimal:
    """Reserve a whole advertised context at router-enforced prices, not guessed tokens."""
    pricing = endpoint["pricing"]
    caps = body["provider"]["max_price"]
    if dollars(pricing.get("request", "0")) != 0:
        raise ValueError("per-request billing has not been admitted for this smoke")
    for field, cap in (("prompt", "prompt"), ("completion", "completion")):
        if dollars(pricing[field]) * 1_000_000 > dollars(caps[cap]):
            raise ValueError("endpoint tariff exceeds the frozen price cap")
    context = endpoint["context_length"]
    if type(context) is not int or context < 1:
        raise ValueError("missing endpoint context ceiling for cost reservation")
    return (
        Decimal(context) * dollars(caps["prompt"])
        + Decimal(body["max_tokens"]) * dollars(caps["completion"])
    ) / 1_000_000


def normalize(record: dict[str, Any], provider: str) -> dict[str, Any]:
    raw = response_json(record)
    if "error" in raw:
        raise ValueError("provider returned an error object; raw response retained")
    if provider == "ollama":
        message = raw.get("message") or {}
        if not isinstance(message, dict):
            raise ValueError("invalid Ollama message envelope")
        return {
            "text": message.get("content"),
            "reasoning": message.get("thinking"),
            "finish_reason": raw.get("done_reason") if raw.get("done") is True else None,
            "actual_model": raw.get("model"),
            "actual_provider": "local-ollama",
            "generation_id": None,
            "system_fingerprint": None,
            "input_tokens": raw.get("prompt_eval_count"),
            "output_tokens": raw.get("eval_count"),
            "reasoning_tokens": None,
            "cached_input_tokens": None,
            "reported_api_cost_usd": "0",
            "cost_origin": "local_no_external_api_charge",
            "timing_ns": {
                k: raw.get(k)
                for k in (
                    "total_duration",
                    "load_duration",
                    "prompt_eval_duration",
                    "eval_duration",
                )
            },
            "usage_origin": "ollama_reported",
            "raw_usage": {
                k: v for k, v in raw.items() if k.endswith("_count") or k.endswith("_duration")
            },
        }
    if provider != "openrouter":
        raise ValueError("unknown provider adapter")
    choices = raw.get("choices") or []
    if not isinstance(choices, list) or any(not isinstance(c, dict) for c in choices):
        raise ValueError("invalid OpenRouter choices envelope")
    choice = choices[0] if len(choices) == 1 else {}
    message = choice.get("message") or {}
    usage = raw.get("usage") or {}
    if (
        not isinstance(message, dict)
        or not isinstance(usage, dict)
        or any(
            not isinstance(usage.get(k) or {}, dict)
            for k in ("completion_tokens_details", "prompt_tokens_details")
        )
    ):
        raise ValueError("invalid OpenRouter message/usage envelope")
    cost = usage.get("cost")
    return {
        "text": message.get("content"),
        "reasoning": message.get("reasoning"),
        "finish_reason": choice.get("finish_reason"),
        "refusal": message.get("refusal"),
        "actual_model": raw.get("model"),
        "actual_provider": raw.get("provider"),
        "generation_id": raw.get("id"),
        "system_fingerprint": raw.get("system_fingerprint"),
        "input_tokens": usage.get("prompt_tokens"),
        "output_tokens": usage.get("completion_tokens"),
        "reasoning_tokens": (usage.get("completion_tokens_details") or {}).get("reasoning_tokens"),
        "cached_input_tokens": (usage.get("prompt_tokens_details") or {}).get("cached_tokens"),
        "reported_api_cost_usd": str(dollars(cost)) if cost is not None else None,
        "cost_origin": "openrouter_usage.cost" if cost is not None else "unavailable",
        "usage_origin": "openrouter_reported",
        "raw_usage": usage,
        "reasoning_count_note": "Reasoning tokens are included in completion_tokens; do not add them again.",
    }

payload.live/calibration_recovery.py:
"""Adopt a stopped local-only calibration without rewriting its original evidence."""

from __future__ import annotations

import ast
from pathlib import Path
from typing import Any

from ..storage import IntegrityError, Store, atomic_write, digest


def scientific_functions(text: str) -> dict[str, str]:
    names = {"reference_request", "summarize_condition", "calibration_gate", "execute"}
    return {
        n.name: ast.dump(n)
        for n in ast.parse(text).body
        if isinstance(n, ast.FunctionDef) and n.name in names
    }


def adopt_local_calibration(parent: Path, target: Path) -> dict[str, Any]:
    source, destination = Store(parent), Store(target)
    with source.lock():
        if source.exists("reports/complete.json") or not source.exists("operator-exit.json"):
            raise IntegrityError("only a stopped incomplete calibration can be adopted")
        old, new = source.get("manifest.json"), destination.get("manifest.json")
        fields = (
            "profile_ids",
            "profile_sha256",
            "local",
            "hosted",
            "gate",
            "local_calls",
            "hosted_calls",
            "total_calls",
        )
        if any(old[k] != new[k] for k in fields):
            raise IntegrityError("calibration scientific manifest changed")
        for name in source.names("inputs/*.json"):
            if name not in ("inputs/source.json", "inputs/protocol.json") and source.get(
                name
            ) != destination.get(name):
                raise IntegrityError("calibration input changed: " + name)
        old_code, new_code = source.get("inputs/source.json"), destination.get("inputs/source.json")
        if any(
            new_code.get(name) != text
            for name, text in old_code.items()
            if name not in ("live/calibrate.py", "live/taskbudget.py")
        ):
            raise IntegrityError("calibration request/scoring/runtime source changed")
        if scientific_functions(old_code["live/calibrate.py"]) != scientific_functions(
            new_code["live/calibrate.py"]
        ):
            raise IntegrityError("calibration scientific functions changed")
        for name in source.names("work/*/attempts/*/request.json"):
            if source.get(name)["provider"] != "ollama":
                raise IntegrityError(
                    "adoption requires local-only attempts; hosted billing must not duplicate"
                )
        hashes = {}
        for folder in ("work", "evaluations", "conditions"):
            for path in sorted((source.root / folder).rglob("*")):
                if not path.is_file():
                    continue
                name = str(path.relative_to(source.root))
                if path.suffix == ".json":
                    payload = source.get(name)
                    destination.put(name, payload)
                    hashes[name] = digest(payload)
                else:
                    atomic_write(destination.root / name, path.read_bytes())
        result = {
            "parent_root": str(source.root.resolve()),
            "parent_manifest_sha256": digest(old),
            "adopted_records": hashes,
            "adopted_commits": len(source.names("work/*/result.json")),
            "parent_clock_not_copied": True,
            "hosted_attempts_adopted": 0,
            "rule": "All local raw attempts and results retained; parent and child clocks charged separately. No parent files changed.",
        }
        destination.put("adoption.json", result)
        return result

payload.live/campaign.py:
"""Shared frozen-runtime preparation, bounded metadata checks and public-data evaluation."""

from __future__ import annotations

import platform
import sys
import time
import uuid
from pathlib import Path
from typing import Any

from ..benchmark.build import load
from ..benchmark.model import BenchmarkProfile, restore_advisory, restore_profile, score
from ..storage import IntegrityError, Store, atomic_write, digest
from .adapters import normalize
from .conditions import executor_request, hosted_conditions, local_conditions, save_registry
from .execution import Execution, StageExhausted
from .generation import generation_metadata
from .preflight import local_identity, sources
from .process import invoke
from .transport import OLLAMA, OPENROUTER, response_json


def prepare(root: Path, benchmark: Path, registry: Path, config: dict[str, Any]) -> dict[str, Any]:
    store = Store(root)
    with store.lock():
        source = sources()
        plan = {
            **config,
            "source_sha256": digest(source),
            "python_version": platform.python_version(),
            "benchmark_sha256": digest(Store(benchmark).get("manifest.json")),
            "source_quality": Store(benchmark)
            .get("manifest.json")
            .get("source_quality", {"status": "not_reviewed"}),
        }
        store.put("plan.json", plan)
        store.put("inputs/source.json", source)
        profiles = load(
            benchmark,
            set(config.get("input_partitions", ["pilot_development", "pilot_validation"])),
        )
        store.put("inputs/profiles.json", [p.record() for p in profiles])
        store.put(
            "inputs/advisories.json", {a.id: a.record() for p in profiles for a in p.advisories}
        )
        model_registry = save_registry(Store(registry), store)
        store.put(
            "inputs/conditions.json",
            {
                "local": local_conditions(model_registry),
                "hosted": hosted_conditions(model_registry),
            },
        )
        for name, text in source.items():
            atomic_write(store.root / "runtime/promptbench" / name, text.encode())
        launcher = (
            "# Frozen runtime: run this file again after an interruption.\n"
            "import os, pathlib, sys\n"
            "root = pathlib.Path(__file__).resolve().parent\n"
            f"python = {sys.executable!r}\n"
            "os.chdir(root / 'runtime')\n"
            f"os.execv(python, [python, '-m', {config.get('runner_module', 'promptbench.live.pilot')!r}, 'run', '--run-dir', str(root), *sys.argv[1:]])\n"
        )
        atomic_write(store.root / "resume.py", launcher.encode())
        return plan


def profiles_from(store: Store) -> list[BenchmarkProfile]:
    advisories = {
        key: restore_advisory(row) for key, row in store.get("inputs/advisories.json").items()
    }
    return [restore_profile(row, advisories) for row in store.get("inputs/profiles.json")]


def verify_runtime(store: Store) -> dict[str, Any]:
    plan = store.get("plan.json")
    if (
        digest(sources()) != plan["source_sha256"]
        or platform.python_version() != plan["python_version"]
    ):
        raise IntegrityError(
            "runtime/Python changed; use this run's frozen resume.py and original interpreter"
        )
    if plan["kind"] == "public_selection_pilot":
        frozen = store.get("preparation.json")
        if frozen["plan_sha256"] != digest(plan) or any(
            digest(store.get(name)) != expected for name, expected in frozen["input_sha256"].items()
        ):
            raise IntegrityError("prepared pilot inputs changed")
    return dict(plan)


class Campaign:
    def __init__(self, execution: Execution):
        self.execution, self.store = execution, execution.store
        self.session = uuid.uuid4().hex
        self.checked: set[str] = set()
        self.last_local: str | None = None
        execution.key_reader = lambda: self.metadata(
            "key", OPENROUTER + "/api/v1/key", authenticated=True
        )

    def metadata(
        self,
        name: str,
        url: str,
        body: dict[str, Any] | None = None,
        *,
        authenticated: bool = False,
    ) -> dict[str, Any]:
        attempt = f"checks/{self.session}/{name}-{uuid.uuid4().hex}"
        remaining = self.execution.remaining_seconds() - 5
        if self.execution.stage_time_left is not None:
            remaining = min(remaining, self.execution.stage_time_left() - 5)
            if remaining < 1:
                raise StageExhausted("exploratory stage time allocation exhausted")
        if remaining < 1:
            from ..runner import RunPaused

            raise RunPaused("no time remains for provider identity check")
        timeout = min(20.0, remaining)
        self.store.put(
            attempt + "/request.json",
            {
                "url": url,
                "body": body,
                "provider": "openrouter" if authenticated else "metadata",
                "timeout_seconds": max(1, int(timeout)),
            },
        )
        self.execution.checkpoint(timeout)
        invoke(
            self.store,
            attempt,
            self.execution.env_file,
            timeout=timeout,
            runtime=self.execution.runtime,
        )
        self.execution.checkpoint()
        return response_json(self.store.get(attempt + "/response.json"))

    def check(self, condition: dict[str, Any]) -> None:
        identifier = condition["id"]
        if condition["provider"] == "ollama":
            model = condition["model"]
            if self.last_local and self.last_local != model:
                self.metadata(
                    "unload",
                    OLLAMA + "/api/generate",
                    {"model": self.last_local, "keep_alive": 0, "stream": False},
                )
                self.checked.discard(identifier)
            self.last_local = model
        if identifier in self.checked:
            return
        if condition["provider"] == "ollama":
            version = self.metadata("version", OLLAMA + "/api/version")["version"]
            tags = self.metadata("tags", OLLAMA + "/api/tags")["models"]
            tag = next((t for t in tags if t["name"] == condition["model"]), None)
            if tag is None:
                raise IntegrityError("frozen local model is no longer installed")
            details = self.metadata("show", OLLAMA + "/api/show", {"model": condition["model"]})
            if local_identity(tag, details, version) != condition["identity"]:
                raise IntegrityError("local model, template, parameters or Ollama version changed")
        else:
            model = condition["model"]
            catalog = self.metadata("catalog", OPENROUTER + "/api/v1/models")["data"]
            entry = next((m for m in catalog if m["id"] == model), None)
            if not entry or entry.get("canonical_slug") != condition["canonical_model"]:
                raise IntegrityError("hosted canonical model changed")
            endpoints = self.metadata(
                "endpoints", OPENROUTER + f"/api/v1/models/{model}/endpoints"
            )["data"]["endpoints"]
            admitted = condition["endpoint"]
            current = next((e for e in endpoints if e["tag"] == admitted["tag"]), None)
            if current is None or any(
                current.get(k) != admitted.get(k)
                for k in ("name", "context_length", "quantization", "provider_name")
            ):
                raise IntegrityError("pinned hosted endpoint identity changed")
            from .adapters import dollars

            if any(
                dollars(current["pricing"][k]) > dollars(admitted["pricing"][k])
                for k in ("prompt", "completion")
            ):
                raise IntegrityError("pinned hosted tariff increased; no silent price update")
        self.checked.add(identifier)

    def evaluate(
        self, prefix: str, condition: dict[str, Any], prompt: str, profiles: list[BenchmarkProfile]
    ) -> list[dict[str, Any]]:
        rows = []
        for profile in profiles:
            self.check(condition)
            key = f"{prefix}/{profile.id}"
            result = self.execution.call(
                key,
                condition,
                executor_request(condition, prompt, profile),
                role="executor",
                allowed_ids={a.id for a in profile.advisories},
            )
            row = score(profile, result["value"], result["status"])
            self.store.put(
                "evaluations/" + digest(key) + ".json",
                {
                    "key": key,
                    "condition_id": condition["id"],
                    "prompt_sha256": digest(prompt),
                    "row": row,
                },
            )
            rows.append(row)
        return rows

    def reconcile_generation(self, attempt: str, canonical_model: str) -> None:
        reply = normalize(self.store.get(attempt + "/response.json"), "openrouter")
        identifier = reply["generation_id"]
        if (
            not isinstance(identifier, str)
            or not identifier.startswith("gen-")
            or not all(c.isalnum() or c in "-_" for c in identifier)
        ):
            raise IntegrityError("hosted response lacks a usable generation identifier")
        name = "generations/" + identifier + ".json"
        if self.store.exists(name):
            return

        def wait(seconds: float) -> None:
            if self.execution.remaining_seconds() < seconds + 5:
                from ..runner import RunPaused

                raise RunPaused("no campaign time for generation metadata retry")
            self.execution.checkpoint(seconds + 5)
            if (
                self.execution.stage_time_left is not None
                and self.execution.stage_time_left() < seconds + 5
            ):
                raise StageExhausted("no stage time for generation metadata retry")
            time.sleep(seconds)

        try:
            data = generation_metadata(self.metadata, wait, identifier, canonical_model)
        except (ValueError, OSError) as exc:
            if isinstance(exc, IntegrityError):
                raise
            self.store.put(
                "generation-pending/" + uuid.uuid4().hex + ".json",
                {"id": identifier, "reason": str(exc), "canonical_model": canonical_model},
            )
            return
        if data.get("model") != canonical_model:
            raise IntegrityError("generation metadata differs from frozen hosted canonical version")
        self.store.put(name, {"id": identifier, "data": data, "canonical_model": canonical_model})

