"""Deterministic teaching fakes: no HTTP, credentials, GPU, or learned models."""

from __future__ import annotations

import json
import math
import re
from dataclasses import asdict, dataclass
from decimal import Decimal
from typing import Any, Protocol

from .domain import Advisory, Component
from .storage import canonical, digest


class ProviderFailure(RuntimeError):
    def __init__(self, message: str, *, retryable: bool):
        super().__init__(message)
        self.retryable = retryable


@dataclass(frozen=True)
class Reply:
    text: str
    finish_reason: str
    provider_request_id: str
    input_tokens: int
    output_tokens: int
    reasoning_tokens: int = 0
    cached_tokens: int = 0

    def record(self) -> dict[str, Any]:
        result = asdict(self)
        result["usage_origin"] = "synthetic_fixture"
        result["tokens_are_estimates"] = True
        result["actual_api_cost_usd"] = "0"
        result["synthetic_cost_usd"] = str(
            Decimal(self.input_tokens) * Decimal("0.000001")
            + Decimal(self.output_tokens) * Decimal("0.000002")
        )
        return result


class Provider(Protocol):
    def call(self, request: dict[str, Any], retry: int, fault: str | None) -> Reply: ...


class FakeProvider:
    def call(self, request: dict[str, Any], retry: int, fault: str | None) -> Reply:
        if fault == "auth":
            raise ProviderFailure("simulated authentication failure", retryable=False)
        if fault == "timeout_always" or (fault == "timeout_once" and retry == 0):
            raise ProviderFailure("simulated transport timeout", retryable=True)
        if request["role"] == "optimizer":
            slot = request["candidate_slot"]
            detail = (
                "Check vendor/product identity."
                if slot == 0
                else "Check both vendor/product identity and version applicability."
            )
            prompt = (
                f"{detail} Return only JSON with applicable_cves. "
                f"Revision {request['iteration']}, variation {slot}, seed {request['seed']}."
            )
            text = json.dumps({"prompt": prompt})
        else:
            data = request["input"]
            # Fictional fixtures have a deliberately small text grammar. The fake
            # consumes the same unstructured input as the default live Executor.
            components = [
                Component(vendor, product, version)
                for vendor, product, version in re.findall(
                    r"(\w+) (\w+) version ([0-9]+(?:\.[0-9]+)*)", data["system_profile"]
                )
            ]
            advisories = [Advisory(**a) for a in data["advisories"]]
            prompt = request["prompt"]
            if "version applicability" in prompt:
                predicted = [a.id for a in advisories if any(a.applies(c) for c in components)]
            elif "vendor/product identity" in prompt:
                predicted = [
                    a.id for a in advisories if any(a.matches_product(c) for c in components)
                ]
            else:
                predicted = [a.id for a in advisories]
            text = json.dumps({"applicable_cves": predicted})
        finish = "stop"
        if fault == "malformed_always" or (fault == "malformed_once" and retry == 0):
            text = '{"incomplete":'
        elif fault == "reasoning_only":
            text, finish = "", "length"
        elif fault == "refusal":
            text, finish = "Simulated refusal", "refusal"
        return Reply(
            text=text,
            finish_reason=finish,
            provider_request_id="fake-" + digest(request)[:24],
            input_tokens=math.ceil(len(canonical(request)) / 4),
            output_tokens=math.ceil(len(text) / 4),
        )

payload.runner.py:
"""Durable per-request execution, typed failures, and bounded recovery."""

from __future__ import annotations

import time
import uuid
from collections.abc import Callable
from datetime import UTC, datetime
from typing import Any

from .domain import ContractError, parse_answer, parse_prompt
from .providers import Provider, ProviderFailure
from .storage import IntegrityError, Store, digest

Hook = Callable[[str, str], None]


class RunPaused(RuntimeError):
    """External/permanent failures or resource caps require an explicit disposition."""


def utc_now() -> str:
    return datetime.now(UTC).isoformat()


def no_hook(point: str, work_id: str) -> None:
    pass


class Runner:
    def __init__(
        self,
        store: Store,
        provider: Provider,
        *,
        max_retries: int,
        max_attempts: int,
        faults: dict[str, str],
        hook: Hook = no_hook,
    ):
        self.store = store
        self.provider = provider
        self.max_retries = max_retries
        self.max_attempts = max_attempts
        self.faults = faults
        self.hook = hook

    def event(self, kind: str, **details: Any) -> None:
        self.store.put(
            f"events/{time.time_ns()}-{uuid.uuid4().hex}.json",
            {
                "timestamp_utc": utc_now(),
                "kind": kind,
                **details,
            },
        )

    def execute(self, key: str, request: dict[str, Any]) -> dict[str, Any]:
        work_id = digest({"key": key, "request": request})
        directory = f"work/{work_id}"
        spec = {"key": key, "request": request, "request_sha256": digest(request)}
        self.store.put(f"{directory}/spec.json", spec)
        self.hook("planned", key)
        result_name = f"{directory}/result.json"
        if self.store.exists(result_name):
            result = self.store.get(result_name)
            self._validate_result(result, spec, directory)
            return dict(result)
        attempts = self.store.names(f"{directory}/attempts/*/request.json")
        retry = 0
        for name in attempts:
            attempt_dir = name.rsplit("/", 1)[0]
            intent = self.store.get(name)
            if intent["request_sha256"] != spec["request_sha256"]:
                raise IntegrityError("attempt request differs from work specification")
            response_name = f"{attempt_dir}/response.json"
            if self.store.exists(response_name):
                response = self.store.get(response_name)
                disposition = self._interpret(request, response)
                self.store.put(f"{attempt_dir}/disposition.json", disposition)
                if disposition["status"] != "retryable":
                    return self._commit(directory, spec, attempt_dir, response, disposition)
                retry = max(retry, intent["retry"] + 1)
            else:
                # An intent without a durable response may already have been billed.
                self.store.put(
                    f"{attempt_dir}/outcome_unknown.json",
                    {
                        "status": "outcome_unknown",
                        "reason": "no durable response after interruption",
                        "actual_api_cost_usd": "0",
                        "synthetic_cost_usd": None,
                        "request_sha256": intent["request_sha256"],
                    },
                )
                # Unknown attempts do not change the logical fake-provider retry state.
                # They DO count against the absolute attempt cap.
                self.event("uncertain_attempt", key=key, attempt=attempt_dir)
        while retry <= self.max_retries:
            if len(self.store.names("work/*/attempts/*/request.json")) >= self.max_attempts:
                raise RunPaused("absolute provider-attempt budget exhausted")
            index = len(self.store.names(f"{directory}/attempts/*/request.json"))
            attempt_dir = f"{directory}/attempts/{index:04d}"
            started = utc_now()
            self.store.put(
                f"{attempt_dir}/request.json",
                {
                    **spec,
                    "attempt_index": index,
                    "retry": retry,
                    "started_utc": started,
                    "model": "deterministic-fake-v1",
                },
            )
            self.event("request_intent", key=key, attempt=attempt_dir)
            self.hook("intent", key)
            start = time.perf_counter_ns()
            try:
                reply = self.provider.call(request, retry, self.faults.get(key))
                response = {"status": "response", "reply": reply.record()}
            except ProviderFailure as exc:
                response = {
                    "status": "transport_error",
                    "error": str(exc),
                    "retryable": exc.retryable,
                    "actual_api_cost_usd": "0",
                    "synthetic_cost_usd": None,
                }
            response.update(
                {
                    "started_utc": started,
                    "finished_utc": utc_now(),
                    "duration_ns": time.perf_counter_ns() - start,
                    "request_sha256": spec["request_sha256"],
                }
            )
            self.hook("provider_returned", key)
            self.store.put(f"{attempt_dir}/response.json", response)
            self.event("response_saved", key=key, attempt=attempt_dir, status=response["status"])
            self.hook("response", key)
            disposition = self._interpret(request, response)
            self.store.put(f"{attempt_dir}/disposition.json", disposition)
            if disposition["status"] != "retryable":
                return self._commit(directory, spec, attempt_dir, response, disposition)
            retry += 1
        if request["role"] == "optimizer":
            raise RunPaused(f"optimizer protocol/transport retries exhausted: {key}")
        # Failure is explicit and no normal empty prediction is fabricated.
        response = self.store.get(f"{attempt_dir}/response.json")
        disposition = {"status": "transport_failure", "value": None}
        return self._commit(directory, spec, attempt_dir, response, disposition)

    def _interpret(
        self,
        request: dict[str, Any],
        response: dict[str, Any],
    ) -> dict[str, Any]:
        if response["request_sha256"] != digest(request):
            raise IntegrityError("response belongs to another request")
        if response["status"] == "transport_error":
            if not response["retryable"]:
                raise RunPaused(response["error"])
            return {"status": "retryable", "value": None, "reason": response["error"]}
        reply = response["reply"]
        try:
            if request["role"] == "optimizer":
                value: Any = parse_prompt(reply["text"], reply["finish_reason"])
            else:
                value = parse_answer(
                    reply["text"],
                    {a["id"] for a in request["input"]["advisories"]},
                    reply["finish_reason"],
                )
            return {"status": "valid", "value": value}
        except ContractError as exc:
            return {
                "status": "retryable" if request["role"] == "optimizer" else "invalid_output",
                "value": None,
                "reason": str(exc),
            }

    def _commit(
        self,
        directory: str,
        spec: dict[str, Any],
        attempt_dir: str,
        response: dict[str, Any],
        disposition: dict[str, Any],
    ) -> dict[str, Any]:
        result = {
            **disposition,
            "key": spec["key"],
            "request_sha256": spec["request_sha256"],
            "response_sha256": digest(response),
            "attempt": attempt_dir,
        }
        self.hook("before_commit", spec["key"])
        self.store.put(f"{directory}/result.json", result)
        self.event("work_committed", key=spec["key"], status=result["status"])
        self.hook("committed", spec["key"])
        return result

    def _validate_result(
        self,
        result: dict[str, Any],
        spec: dict[str, Any],
        directory: str,
    ) -> None:
        if result["key"] != spec["key"] or result["request_sha256"] != spec["request_sha256"]:
            raise IntegrityError("committed result differs from work specification")
        if not result["attempt"].startswith(directory + "/attempts/"):
            raise IntegrityError("result references another work item")
        response = self.store.get(result["attempt"] + "/response.json")
        if result["response_sha256"] != digest(response):
            raise IntegrityError("committed response changed")

payload.storage.py:
"""Atomic immutable records. All durable evidence lives in the requested run folder."""

from __future__ import annotations

import fcntl
import hashlib
import json
import os
import tempfile
from collections.abc import Iterator
from contextlib import contextmanager
from pathlib import Path
from typing import Any


class IntegrityError(ValueError):
    """A saved record is corrupt or conflicts with the requested run."""


def canonical(value: Any) -> str:
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    )


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def atomic_write(path: Path, content: bytes, *, immutable: bool = True) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if immutable and path.exists():
        if path.read_bytes() != content:
            raise IntegrityError(f"immutable artifact conflicts: {path}")
        return
    fd, temp = tempfile.mkstemp(prefix=".pending-", dir=path.parent)
    temporary = Path(temp)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        if immutable:
            try:
                os.link(temporary, path)
            except FileExistsError:
                if path.read_bytes() != content:
                    raise IntegrityError(f"concurrent artifact conflict: {path}") from None
        else:
            os.replace(temporary, path)
        directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        temporary.unlink(missing_ok=True)


def read_jsonl(path: Path) -> list[Any]:
    """Read physical JSONL records without treating Unicode text separators as rows."""
    with path.open(encoding="utf-8") as stream:
        return [json.loads(line) for line in stream]


class Store:
    def __init__(self, root: Path):
        self.root = root.resolve()

    def put(self, name: str, payload: Any, *, immutable: bool = True) -> str:
        checksum = digest(payload)
        record = {"sha256": checksum, "payload": payload}
        atomic_write(self.root / name, (canonical(record) + "\n").encode(), immutable=immutable)
        return checksum

    def get(self, name: str) -> Any:
        path = self.root / name
        try:
            record = json.loads(path.read_text())
            payload = record["payload"]
            if set(record) != {"sha256", "payload"} or digest(payload) != record["sha256"]:
                raise IntegrityError(f"checksum mismatch: {name}")
            return payload
        except (OSError, ValueError, KeyError, TypeError) as exc:
            raise IntegrityError(f"cannot validate record: {name}") from exc

    def exists(self, name: str) -> bool:
        return (self.root / name).exists()

    def names(self, pattern: str) -> list[str]:
        return sorted(str(path.relative_to(self.root)) for path in self.root.glob(pattern))

    @contextmanager
    def lock(self) -> Iterator[None]:
        # This is a disposable local process lock, not experimental data.
        lock_root = Path(tempfile.gettempdir()) / f"promptbench-locks-{os.getuid()}"
        lock_root.mkdir(mode=0o700, exist_ok=True)
        path = lock_root / (hashlib.sha256(str(self.root).encode()).hexdigest() + ".lock")
        with path.open("a") as lock:
            try:
                fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                raise IntegrityError("another controller owns this run") from None
            try:
                self.root.mkdir(parents=True, exist_ok=True)
                yield
            finally:
                fcntl.flock(lock, fcntl.LOCK_UN)
